import { GoogleGenAI, Chat, GenerateContentResponse, Content } from "@google/genai";
import { Message, CaseSummary, Attachment, GroundingSource } from "../types";

// Instrucción maestra para el SaaS Legal - Optimizada para fluidez narrativa
const SYSTEM_INSTRUCTION = `
ERES "JUSTINO", EL ASISTENTE LEGAL VISIONARIO LÍDER EN MÉXICO.
TU MISIÓN: Proveer claridad, estrategia y fundamentación legal instantánea mediante una conversación fluida y profesional.

REGLA DE ORO DE INTERACCIÓN:
- NO uses subtítulos rígidos, encabezados en mayúsculas o secciones marcadas con corchetes (ej. evita "[ANÁLISIS]" o "### INDAGACIÓN").
- Tu respuesta debe ser fluida, como si estuvieras hablando con un cliente en tu despacho. Integra la estructura lógica dentro de tus párrafos.

PROTOCOLO DE RESPUESTA NATURAL:
1. Comienza validando lo que el usuario te ha dicho de forma empática y directa.
2. Si necesitas más datos (Fase de Indagación), intégralos como parte de la conversación: "Para poder darte una ruta exacta, necesito que me ayudes aclarando algunos puntos: [tus preguntas aquí]".
3. Solo cuando tengas datos suficientes, menciona los fundamentos legales y la ruta de acción, pero siempre de forma narrativa.

DIRECTRICES DE TONO:
- LENGUAJE: Autoridad absoluta pero accesible. Sin "legalese" innecesario.
- ÉTICA: Mantén siempre la advertencia de que eres una IA de apoyo.
- MÉXICO: Todo el contexto debe estar basado en leyes mexicanas vigentes.

TU OBJETIVO ES QUE EL USUARIO SE SIENTA ACOMPAÑADO, NO QUE ESTÁ LEYENDO UN REPORTE TÉCNICO.
`;

const getHistory = (messages: Message[]): Content[] => {
  return messages
    .filter(m => m.id !== 'welcome' && m.id !== 'error')
    .map(m => ({
      role: m.sender === 'user' ? 'user' : 'model',
      parts: [{ text: m.text }]
    }));
};

export const sendMessageToJustino = async (
  message: string, 
  history: Message[],
  attachment?: Attachment
): Promise<{text: string, sources: GroundingSource[]}> => {

  // Inicialización con la API Key del entorno (SaaS Security Standard)
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const modelName = 'gemini-3-pro-preview';

  const chat = ai.chats.create({
    model: modelName,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      temperature: 0.15,
      tools: [{ googleSearch: {} }],
      thinkingConfig: { thinkingBudget: 12000 }
    },
    history: getHistory(history),
  });

  try {
    let result: GenerateContentResponse;

    if (attachment) {
      const dataPart = {
        inlineData: {
          mimeType: attachment.type,
          data: attachment.content.includes(',') ? attachment.content.split(',')[1] : attachment.content
        }
      };
      const textPart = { text: message || "Analiza este documento bajo la ley mexicana y dime qué preguntas debo responder para entender mi situación legal." };
      result = await chat.sendMessage({ message: [textPart, dataPart] });
    } else {
      result = await chat.sendMessage({ message });
    }

    const text = result.text || "He procesado tu información. Para darte una estrategia ganadora, necesito que respondas algunas preguntas adicionales.";
    const sources: GroundingSource[] = [];

    // Extracción de fuentes de Google Search (Grounding)
    const chunks = result.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
      chunks.forEach((chunk: any) => {
        if (chunk.web && chunk.web.uri) {
          sources.push({
            title: chunk.web.title || "Legislación/Fuente Oficial",
            uri: chunk.web.uri
          });
        }
      });
    }

    return { text, sources };
  } catch (error: any) {
    console.error("Justino SaaS Engine Error:", error);
    if (error.message?.includes("API key not found")) {
        throw new Error("Error de configuración de red. Contacta a soporte.");
    }
    throw error;
  }
};

export const generateCaseSummary = async (messages: Message[]): Promise<CaseSummary> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const context = messages.slice(-15).map(m => `${m.sender}: ${m.text}`).join('\n');
  const prompt = `Actúa como un actuario legal. Resume este expediente para el cliente. Devuelve exclusivamente JSON: {"antecedents": ["lista de hechos clave"], "recommendedActions": ["lista de pasos legales sugeridos"]}.\n\nExpediente:\n${context}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: { 
        responseMimeType: 'application/json',
        temperature: 0.1 
      }
    });
    const parsed = JSON.parse(response.text || "{}");
    return {
      antecedents: parsed.antecedents || [],
      recommendedActions: parsed.recommendedActions || [],
      lastUpdated: new Date()
    };
  } catch (e) {
    return { antecedents: [], recommendedActions: [], lastUpdated: new Date() };
  }
};

